msg.payload = {
    student: "Коростелкина Диана Алексеевна",
    group: "СДП-УИР-241"
};
return msg;

// Данные (массив объектов)
const items = [
    { id: 1, name: "Ноутбук", price: 1500 },
    { id: 2, name: "Мышь", price: 50 },
    { id: 3, name: "Клавиатура", price: 120 },
    { id: 4, name: "Монитор", price: 600 }
];

let status = 200;
let body;

if (msg.req.params.id !== undefined) {
    // вариант 1: /api/items/:id  (path param)
    const id = Number(msg.req.params.id);
    if (!Number.isInteger(id) || id < 1) {
        status = 400;
        body = { error: "Bad Request", message: "id должен быть положительным целым числом" };
    } else {
        const found = items.find(function (item) { return item.id === id; });
        if (!found) {
            status = 404;
            body = { error: "Not Found", message: "Элемент с id " + id + " не найден" };
        } else {
            body = found;
        }
    }
} else {
    // вариант 2: /api/items?limit=N  (query param)
    let limit = items.length;
    if (msg.req.query.limit !== undefined) {
        const l = Number(msg.req.query.limit);
        if (!Number.isInteger(l) || l < 1) {
            status = 400;
            body = { error: "Bad Request", message: "limit должен быть положительным целым числом" };
        } else {
            limit = l;
        }
    }
    if (status === 200) {
        const list = [];
        for (let i = 0; i < items.length && i < limit; i++) {
            list.push(items[i]);
        }
        body = list;
    }
}

msg.statusCode = status;
msg.payload = body;
return msg;
